import type {
  RowClickEvent,
  TableCellType,
  TableDataType,
} from 'components/TableComponent';

import type { DemographicGroup, InteractiveRowSelection } from '../../../types';

const normalize = (label: string): string => label.toLowerCase().trim();

const GROUP_MATCHERS: Array<{
  matches: (label: string) => boolean;
  group: DemographicGroup;
}> = [
  {
    matches: (l) => l.includes('gender') || l.includes('sex'),
    group: 'gender',
  },
  { matches: (l) => l.includes('age'), group: 'age' },
  { matches: (l) => l.includes('income'), group: 'income' },
];

export const extractCellValue = (
  cell: TableCellType | string | number | boolean | undefined,
): string | null => {
  if (cell == null || typeof cell === 'boolean') return null;
  if (typeof cell === 'string') return cell;
  if (typeof cell === 'number') return String(cell);
  if (typeof cell === 'object' && 'value' in cell) {
    return cell.value == null ? null : String(cell.value);
  }
  return null;
};

export const resolveDemographicGroup = (
  label: string | null | undefined,
): DemographicGroup | null => {
  if (!label) return null;
  const normalized = normalize(label);
  return GROUP_MATCHERS.find((m) => m.matches(normalized))?.group ?? null;
};

export const resolveRowSelection = (
  data: TableDataType | null,
  event: RowClickEvent,
): InteractiveRowSelection | null => {
  const segment = event.context?.rowLabel;
  const segmentStr = segment == null ? '' : String(segment).trim();
  if (!segmentStr) return null;

  const groupRows = data?.rows?.[event.groupIndex];
  const firstRow = groupRows?.[0] as
    Record<string, TableCellType | string | number | boolean> | undefined;
  const rowGroupLabel = firstRow
    ? extractCellValue(firstRow['rowGroupLabel'])
    : null;

  const group = resolveDemographicGroup(rowGroupLabel);
  if (!group) return null;

  return { group, segment: segmentStr };
};
